svg.script:
(function(){
  window.countryClicked = function(id){
    var el = document.getElementById(id);
    if(!el) return;
    document.querySelectorAll('.country.selected').forEach(function(n){n.classList.remove('selected');});
    el.classList.add('selected');
    window.selectedCountryId = id;
    document.dispatchEvent(new CustomEvent('countryclick', {detail:{id:id, element:el}}));
  };
  document.addEventListener('keydown', function(e){
    if(e.key === 'Enter' && document.activeElement && document.activeElement.classList.contains('country')){
      window.countryClicked(document.activeElement.id);
    }
  });
})();

let selectedCountry = null;

function countryClicked(id) {
    // Restore the previous country
    if (selectedCountry) {
        selectedCountry.style.fill = selectedCountry.dataset.originalColor;
    }

    // Select the new country
    const country = document.getElementById(id);

    // Remember its original color
    if (!country.dataset.originalColor) {
        country.dataset.originalColor =
            country.getAttribute('fill') || 'none';
    }

    country.style.fill = '#FFF2B2';
    selectedCountry = country;
}
